from pathlib import Path
from urllib.parse import urlparse

from pydantic import SecretStr, field_validator
from pydantic_settings import BaseSettings, SettingsConfigDict


class Settings(BaseSettings):
    """Application configuration loaded from environment variables."""

    model_config = SettingsConfigDict(env_file=".env", extra="ignore")

    app_env: str = "development"
    log_level: str = "INFO"
    database_url: str = "sqlite:////data/workboard.db"
    microsoft_tenant_id: str | None = None
    microsoft_client_id: str | None = None
    microsoft_client_secret: SecretStr | None = None
    microsoft_target_user_id: str | None = None
    microsoft_redirect_uri: str = "http://localhost:8787/api/auth/callback"
    app_encryption_key: SecretStr | None = None
    # Distinct from Graph/OAuth secrets. Installed local agents use this only
    # as ``Authorization: Bearer ...`` when accessing the agent protocol.
    local_api_token: SecretStr | None = None
    local_session_ttl_seconds: int = 28_800
    max_request_body_bytes: int = 1_048_576
    token_store_path: Path = Path("/data/workboard-graph-tokens.json")
    oauth_state_store_path: Path = Path("/data/workboard-oauth-state.json")

    @field_validator("microsoft_redirect_uri")
    @classmethod
    def redirect_uri_is_safe(cls, value: str) -> str:
        """Only allow a local development callback over HTTP."""
        parsed = urlparse(value)
        if parsed.path != "/api/auth/callback":
            raise ValueError("MICROSOFT_REDIRECT_URI must end in /api/auth/callback")
        if parsed.scheme == "https" or (parsed.scheme == "http" and parsed.hostname in {"localhost", "127.0.0.1"}):
            return value
        raise ValueError("MICROSOFT_REDIRECT_URI must use HTTPS or localhost HTTP")

    @field_validator("microsoft_tenant_id", "microsoft_client_id", "microsoft_target_user_id")
    @classmethod
    def graph_identifiers_are_not_urls(cls, value: str | None) -> str | None:
        if value is not None and (not value.strip() or any(char in value for char in "/\\?&#")):
            raise ValueError("Microsoft identifiers must be plain tenant, client, or object IDs")
        return value

    def graph_configuration_errors(self) -> list[str]:
        required = {
            "MICROSOFT_TENANT_ID": self.microsoft_tenant_id,
            "MICROSOFT_CLIENT_ID": self.microsoft_client_id,
            "MICROSOFT_CLIENT_SECRET": self.microsoft_client_secret,
            "MICROSOFT_TARGET_USER_ID": self.microsoft_target_user_id,
            "APP_ENCRYPTION_KEY": self.app_encryption_key,
        }
        def present(value: str | SecretStr | None) -> bool:
            if isinstance(value, SecretStr):
                return bool(value.get_secret_value().strip())
            return bool(value and value.strip())
        return [name for name, value in required.items() if not present(value)]


@lru_cache
def get_settings() -> Settings:
    return Settings()

"""Narrow, read-only Microsoft Graph client with injectable transport for tests."""

from __future__ import annotations

from collections.abc import Callable
from typing import Any
from urllib.parse import quote
from urllib.request import Request, urlopen

GRAPH_ROOT = "https://graph.microsoft.com/v1.0"
Transport = Callable[[str, str, dict[str, str], dict[str, Any] | None], dict[str, Any]]


class GraphError(RuntimeError):
    pass


def default_transport(method: str, url: str, headers: dict[str, str], payload: dict[str, Any] | None) -> dict[str, Any]:
    if method != "GET":
        raise GraphError("Graph connector permits read-only GET requests")
    request = Request(url, headers=headers, method="GET")
    try:
        import json
        with urlopen(request, timeout=15) as response:  # nosec B310: fixed Microsoft endpoint
            return json.loads(response.read())
    except Exception as error:  # transport details can contain sensitive request metadata
        raise GraphError("Microsoft Graph request failed") from error


class GraphClient:
    def __init__(self, access_token: str, transport: Transport = default_transport) -> None:
        self._headers = {"Authorization": f"Bearer {access_token}", "Accept": "application/json"}
        self._transport = transport

    def _get(self, path: str) -> dict[str, Any]:
        return self._transport("GET", f"{GRAPH_ROOT}{path}", self._headers, None)

    def me(self) -> dict[str, Any]:
        # ``mail`` can differ from the principal name on alias-domain tenants; the
        # promotion heuristic accepts mail addressed to either.
        return self._get("/me?$select=id,userPrincipalName,mail")

    def inbox_messages(self, limit: int = 50) -> list[dict[str, Any]]:
        # Recipients and headers are what the promotion heuristic reads to tell mail
        # addressed to the user from a bulk mailing; both are returned only on $select.
        select = "id,subject,bodyPreview,webLink,receivedDateTime,from,toRecipients,internetMessageHeaders"
        path = f"/me/mailFolders/inbox/messages?$top={limit}&$select={quote(select, safe=',')}"
        return self._get(path).get("value", [])

    def chat_messages(self, limit: int = 50) -> list[dict[str, Any]]:
        chats = self._get(f"/me/chats?$top={limit}&$select=id,topic").get("value", [])
        messages: list[dict[str, Any]] = []
        for chat in chats[:limit]:
            chat_id = chat.get("id")
            if not chat_id:
                continue
            rows = self._get(f"/chats/{quote(str(chat_id), safe='')}/messages?$top={limit}&$select=id,body,createdDateTime,webUrl,from").get("value", [])
            for row in rows:
                row["chatTopic"] = chat.get("topic")
                row["chatId"] = chat_id
            messages.extend(rows)
        return messages[:limit]

"""Small encrypted local storage primitive for OAuth refresh tokens."""

from __future__ import annotations

import base64
import binascii
import json
import os
from pathlib import Path
from typing import Any

from cryptography.exceptions import InvalidTag
from cryptography.hazmat.primitives.ciphers.aead import AESGCM


class TokenStoreError(RuntimeError):
    pass


class EncryptedTokenStore:
    """A single encrypted file; never return its ciphertext to an API client."""

    def __init__(self, path: Path, key: str) -> None:
        try:
            self._cipher = AESGCM(base64.urlsafe_b64decode(key.encode()))
        except (ValueError, TypeError, binascii.Error) as error:
            raise TokenStoreError("APP_ENCRYPTION_KEY must be a 32-byte URL-safe base64 key") from error
        self.path = path

    def save(self, token: dict[str, Any]) -> None:
        payload = json.dumps(token, separators=(",", ":")).encode()
        self.path.parent.mkdir(parents=True, exist_ok=True)
        nonce = os.urandom(12)
        self.path.write_bytes(nonce + self._cipher.encrypt(nonce, payload, b"workboard-graph-v1"))
        self.path.chmod(0o600)

    def load(self) -> dict[str, Any] | None:
        if not self.path.exists():
            return None
        try:
            raw = self.path.read_bytes()
            return json.loads(self._cipher.decrypt(raw[:12], raw[12:], b"workboard-graph-v1"))
        except (InvalidTag, ValueError, json.JSONDecodeError) as error:
            raise TokenStoreError("stored Graph token cannot be decrypted") from error

    def clear(self) -> None:
        if self.path.exists():
            self.path.unlink()


def generate_encryption_key() -> str:
    """Useful for setup tooling; do not generate a replacement key at runtime."""
    return base64.urlsafe_b64encode(os.urandom(32)).decode()

